def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if not prettyprint:
        indent = ''
    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = instance.gpx_11_fields

    attributes = []
    if custom_attributes:
        for attr_name, attr_value in custom_attributes.items():
            attributes.append(f' {attr_name}="{attr_value}"')

    node_body: List[str] = []
    current_path: List[Optional[str]] = []

    for gpx_field in fields:
        if isinstance(gpx_field, str):
            sentinel, fieldname = _check_dependents(instance, gpx_field)
            if gpx_field.partition(':')[0].startswith('/'):
                if current_path:
                    closed = current_path.pop()
                    if closed is not None:
                        node_body.append(f'\n{indent}{"  " * len(current_path)}</{closed}>')
            else:
                if sentinel:
                    current_path.append(None)
                else:
                    node_body.append(f'\n{indent}{"  " * len(current_path)}<{fieldname}>')
                    current_path.append(fieldname)
        else:
            value = getattr(instance, gpx_field.name)
            if gpx_field.attribute:
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint, indent)
                if xml_value:
                    attributes.append(f' {xml_value}')
            else:
                field_indent = indent + '  ' * len(current_path)
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint, field_indent)
                if xml_value:
                    node_body.append(xml_value)

    body_str = ''.join(node_body)
    attrs_str = ''.join(attributes)

    if not body_str and empty_body:
        return f'\n{indent}<{tag}{attrs_str} />'
    elif not body_str:
        return f'\n{indent}<{tag}{attrs_str} />'
    else:
        return f'\n{indent}<{tag}{attrs_str}>{body_str}\n{indent}</{tag}>'
